import React, { PropsWithChildren } from "react";
import { DocsContainer, DocsContainerProps } from "@storybook/blocks";
import LinkTo from "@storybook/addon-links/react";
import Link from "../src/components/Link";
import GLightbox from "glightbox";

const SBDocsContainer = ({
  children,
  context,
}: PropsWithChildren<DocsContainerProps>) => {
  // lightbox support to zoom images in mdx docs
  React.useEffect(() => {
    const lightbox = GLightbox({
      selector: ".glightbox",
      touchNavigation: true,
      loop: true,
    });
    return () => {
      lightbox.destroy();
    };
  }, []);

  return (
    <DocsContainer context={context}>
      <div className="announcement">
        <Link
          inline
          href="https://github.airbus.corp/Airbus/design-system/discussions/2583"
          target="_blank"
        >Version 3.0.0 is stable</Link> !&nbsp;
        Follow <LinkTo kind="General/Migration/v2-to-v3" story="docs">migration guidelines</LinkTo> to benefit from the latest improvements.
        (Previous <Link href="https://react.design-system.airbus.corp/v2/" target="_blank">v2.x documentation</Link>)
      </div>
      {children}
    </DocsContainer>
  );
};

export default SBDocsContainer;
